package org.apache.commons.cli;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.cli.Option;
import org.apache.commons.cli.OptionBuilder;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;

public class OptionBuilder_create_TriageGen0Test {

    @Test
    public void testCreateWithOpt() throws Exception {
        // Given
        String opt = "testOpt";

        // When
        Option option = OptionBuilder.create(opt);

        // Then
        assertEquals(opt, option.getOpt());
    }

    @Test
    public void testCreateWithLongOpt() throws Exception {
        // Given
        String longOpt = "testLongOpt";
        OptionBuilder optionBuilder = OptionBuilder.withLongOpt(longOpt);

        // When
        Option option = optionBuilder.create("testOpt");

        // Then
        assertEquals(longOpt, option.getLongOpt());
    }

    @Test
    public void testCreateWithRequired() throws Exception {
        // Given
        OptionBuilder optionBuilder = OptionBuilder.isRequired();

        // When
        Option option = optionBuilder.create("testOpt");

        // Then
        assertEquals(true, option.isRequired());
    }

    @Test
    public void testCreateWithOptionalArg() throws Exception {
        // Given
        OptionBuilder optionBuilder = OptionBuilder.hasOptionalArg();

        // When
        Option option = optionBuilder.create("testOpt");

        // Then
        assertEquals(true, option.hasOptionalArg());
    }

    @Test
    public void testCreateWithArgs() throws Exception {
        // Given
        OptionBuilder optionBuilder = OptionBuilder.hasArgs();

        // When
        Option option = optionBuilder.create("testOpt");

        // Then
        assertEquals(0, option.getArgs());
    }

    @Test
    public void testCreateWithType() throws Exception {
        // Given
        Object type = "testType";
        OptionBuilder optionBuilder = OptionBuilder.withType(type);

        // When
        Option option = optionBuilder.create("testOpt");

        // Then
        assertEquals(type, option.getType());
    }

    @Test
    public void testCreateWithValueSeparator() throws Exception {
        // Given
        OptionBuilder optionBuilder = OptionBuilder.withValueSeparator(',');

        // When
        Option option = optionBuilder.create("testOpt");

        // Then
        assertEquals(',', option.getValueSeparator());
    }

    @Test
    public void testCreateWithArgName() throws Exception {
        // Given
        OptionBuilder optionBuilder = OptionBuilder.withArgName("testArgName");

        // When
        Option option = optionBuilder.create("testOpt");

        // Then
        assertEquals("testArgName", option.getArgName());
    }

    @Test
    public void testCreateWithInvalidOpt() throws Exception {
        // Given
        String opt = null;

        // When
        assertThrows(IllegalArgumentException.class, () -> OptionBuilder.create(opt));
    }

    @Test
    public void testCreateWithoutOpt() throws Exception {
        // Given
        String opt = "";

        // When
        assertThrows(IllegalArgumentException.class, () -> OptionBuilder.create(opt));
    }
}
